  "ev.career.separate_start.fact": "\u0e40\u0e2a\u0e49\u0e19 crieth \u0e40\u0e2a\u0e49\u0e19 \u0e0a\u0e35\u0e27\u0e34\u0e15 \u0e40\u0e23\u0e34\u0e48\u0e21 \u0e41\u0e22\u0e01 \u0e08\u0e32\u0e01 \u0e01\u0e31\u0e19",
