  "ev.career.joined_start.fact": "\u0e40\u0e2a\u0e49\u0e19\u0e0a\u0e35\u0e27\u0e34\u0e15\u0e41\u0e25\u0e30\u0e2b\u0e31\u0e27\u0e40\u0e23\u0e34\u0e48\u0e21\u0e15\u0e49\u0e19 grandmother \u0e14\u0e49\u0e27\u0e22\u0e01\u0e31\u0e19",
  "ev.career.joined_start.meaning": "\u0e02\u0e49\u0e2d \u0e04\u0e31\u0e21\u0e20\u0e35\u0e23\u0e4c \u0e17\u0e35\u0e48 \u0e40\u0e23\u0e34\u0e48\u0e21 \u0e15\u0e49\u0e19 \u0e14\u0e49\u0e27\u0e22 \u0e01\u0e31\u0e19 \u0e1a\u0e48\u0e07 \u0e0a\u0e35\u0e49 \u0e16\u0e36\u0e07 \u0e27\u0e34\u0e18\u0e35 \u0e17\u0e4d\u0e32 \u0e07\u0e32\u0e19 \u0e17\u0e35\u0e48 \u0e23\u0e30\u0e21\u0e31\u0e14\u0e23\u0e30\u0e27\u0e31\u0e07 \u0e41\u0e25\u0e30 \u0e44\u0e27\u0e49 \u0e43\u0e08 \u0e44\u0e14\u0e49.",
  "ev.career.head_clear.fact": "\u0e40\u0e2a\u0e49\u0e19\u0e2a\u0e21\u0e2d\u0e07 clarity: {p} (clear)",
  "ev.career.head_clear.meaning": "\u0e40\u0e2a\u0e49\u0e19\u0e2b\u0e31\u0e27\u0e17\u0e35\u0e48\u0e0a\u0e31\u0e14\u0e40\u0e08\u0e19 \u0e1a\u0e48\u0e07\u0e1a\u0e2d\u0e01\u0e16\u0e36\u0e07\u0e42\u0e1f\u0e01\u0e31\u0e2a\u0e17\u0e35\u0e48\u0e22\u0e2d\u0e14\u0e40\u0e22\u0e35\u0e48\u0e22\u0e21",
  "ev.career.heart_index.fact": "\u0e40\u0e2a\u0e49\u0e19\u0e2b\u0e31\u0e27\u0e43\u0e08 reaches under the index finger",
  "ev.career.heart_index.meaning": "\u0e40\u0e2a\u0e49\u0e19 \u0e2b\u0e31\u0e27\u0e43\u0e08 \u0e15\u0e48\u0e2d \u0e19\u0e34\u0e49\u0e27 \u0e0a\u0e35\u0e49 (\u0e22\u0e2d\u0e14 \u0e14\u0e32\u0e27 \u0e1e\u0e24\u0e2b\u0e31\u0e2a\u0e1a\u0e14\u0e35) \u0e1a\u0e48\u0e07 \u0e0a\u0e35\u0e49 \u0e16\u0e36\u0e07 \u0e1c\u0e39\u0e49 \u0e19\u0e4d\u0e32 \u0e15\u0e32\u0e21 \u0e18\u0e23\u0e23\u0e21\u0e0a\u0e32\u0e15\u0e34 \u0e0b\u0e36\u0e48\u0e07 \u0e0a\u0e31\u0e01 \u0e19\u0e4d\u0e32 \u0e1c\u0e39\u0e49 \u0e04\u0e19 \u0e43\u0e2b\u0e49 \u0e40\u0e02\u0e49\u0e32 \u0e21\u0e32.",
  "ev.default.wealth": "\u0e44\u0e21\u0e48 \u0e21\u0e35 \u0e2d\u0e30\u0e44\u0e23 \u0e43\u0e19 \u0e1d\u0e48\u0e32 \u0e21\u0e37\u0e2d \u0e02\u0e2d\u0e07 \u0e04\u0e38\u0e13 \u0e17\u0e35\u0e48 \u0e40\u0e2b\u0e21\u0e32\u0e30 \u0e2a\u0e4d\u0e32\u0e2b\u0e23\u0e31\u0e1a \u0e42\u0e0a\u0e04 \u0e25\u0e32\u0e20 \u2014 \u0e19\u0e31\u0e48\u0e19 \u0e01\u0e47 \u0e04\u0e37\u0e2d \u0e15\u0e49\u0e19 \u0e1b\u0e32\u0e25\u0e4c\u0e21 \u0e42\u0e14\u0e22 \u0e40\u0e09\u0e25\u0e35\u0e48\u0e22 \u0e17\u0e35\u0e48 \u0e19\u0e35\u0e48 \u0e14\u0e31\u0e07 \u0e19\u0e31\u0e49\u0e19 \u25cb0 \u25cb \u0e08\u0e36\u0e07 \u0e40\u0e1b\u0e47\u0e19 \u0e1e\u0e25\u0e31\u0e07\u0e07\u0e32\u0e19 \u0e1e\u0e37\u0e49\u0e19 \u0e10\u0e32\u0e19 \u0e02\u0e2d\u0e07 \u0e04\u0e38\u0e13.{n} is your baseline energy.",
  "ev.default.love": "\u0e44\u0e21\u0e48 \u0e21\u0e35 \u0e2d\u0e30\u0e44\u0e23 \u0e43\u0e19 \u0e21\u0e37\u0e2d \u0e02\u0e2d\u0e07 \u0e04\u0e38\u0e13 \u0e41\u0e2a\u0e14\u0e07 \u0e27\u0e48\u0e32 \u0e04\u0e38\u0e13 \u0e23\u0e31\u0e01 \u0e42\u0e0a\u0e04 \u0e14\u0e35 \u2014 \u0e19\u0e31\u0e48\u0e19 \u0e2b\u0e21\u0e32\u0e22 \u0e04\u0e27\u0e32\u0e21 \u0e27\u0e48\u0e32 \u0e21\u0e35 \u0e15\u0e49\u0e19 \u0e1b\u0e32\u0e25\u0e4c\u0e21 \u0e42\u0e14\u0e22 \u0e40\u0e09\u0e25\u0e35\u0e48\u0e22 \u0e17\u0e35\u0e48 \u0e19\u0e35\u0e48 \u0e40\u0e2d\u0e07 \u0e14\u0e31\u0e07 \u0e19\u0e31\u0e49\u0e19 \u25cb0 \u25cb \u0e08\u0e36\u0e07 \u0e40\u0e1b\u0e47\u0e19 \u0e1e\u0e25\u0e31\u0e07\u0e07\u0e32\u0e19 \u0e1e\u0e37\u0e49\u0e19 \u0e10\u0e32\u0e19 \u0e02\u0e2d\u0e07 \u0e04\u0e38\u0e13.{n} is your baseline energy.",
  "ev.default.health": "\u0e44\u0e21\u0e48 \u0e21\u0e35 \u0e2d\u0e30\u0e44\u0e23 \u0e43\u0e19 \u0e21\u0e37\u0e2d \u0e02\u0e2d\u0e07 \u0e04\u0e38\u0e13 \u0e14\u0e39 \u0e40\u0e2b\u0e21\u0e37\u0e2d\u0e19 \u0e42\u0e0a\u0e04 \u0e14\u0e35 \u2014 \u0e19\u0e31\u0e48\u0e19 \u0e01\u0e47 \u0e41\u0e04\u0e48 \u0e2b\u0e21\u0e32\u0e22 \u0e16\u0e36\u0e07 \u0e15\u0e49\u0e19 \u0e1b\u0e32\u0e25\u0e4c\u0e21 \u0e42\u0e14\u0e22 \u0e40\u0e09\u0e25\u0e35\u0e48\u0e22 \u0e17\u0e35\u0e48 \u0e19\u0e35\u0e48 \u0e14\u0e31\u0e07 \u0e19\u0e31\u0e49\u0e19 \u25cb \u25cb \u25cb \u0e08\u0e36\u0e07 \u0e40\u0e1b\u0e47\u0e19 \u0e1e\u0e25\u0e31\u0e07 \u0e07\u0e32\u0e19 \u0e1e\u0e37\u0e49\u0e19 \u0e10\u0e32\u0e19 \u0e02\u0e2d\u0e07 \u0e04\u0e38\u0e13.{n} is your baseline energy.",
  "ev.default.career": "\u0e44\u0e21\u0e48 \u0e21\u0e35 \u0e2d\u0e30\u0e44\u0e23 \u0e43\u0e19 \u0e1d\u0e48\u0e32 \u0e21\u0e37\u0e2d \u0e02\u0e2d\u0e07 \u0e04\u0e38\u0e13 \u0e17\u0e35\u0e48 \u0e41\u0e2a\u0e14\u0e07 \u0e16\u0e36\u0e07 \u0e42\u0e0a\u0e04 \u0e25\u0e32\u0e20 \u0e43\u0e19 \u0e01\u0e32\u0e23 \u0e17\u0e4d\u0e32 \u0e07\u0e32\u0e19 \u2014 \u0e19\u0e31\u0e48\u0e19 \u0e40\u0e1e\u0e35\u0e22\u0e07 \u0e41\u0e15\u0e48 \u0e2b\u0e21\u0e32\u0e22 \u0e16\u0e36\u0e07 \u0e15\u0e49\u0e19 \u0e1b\u0e32\u0e25\u0e4c\u0e21 \u0e42\u0e14\u0e22 \u0e40\u0e09\u0e25\u0e35\u0e48\u0e22 \u0e17\u0e35\u0e48 \u0e19\u0e35\u0e48 \u0e14\u0e31\u0e07 \u0e19\u0e31\u0e49\u0e19 \u25cb0 \u25cb \u0e08\u0e36\u0e07 \u0e40\u0e1b\u0e47\u0e19 \u0e1e\u0e25\u0e31\u0e07\u0e07\u0e32\u0e19 \u0e1e\u0e37\u0e49\u0e19 \u0e10\u0e32\u0e19 \u0e02\u0e2d\u0e07 \u0e04\u0e38\u0e13.{n} is your baseline energy.",
