  "type.fire.name": "\u0e08\u0e34\u0e49\u0e07\u0e08\u0e2d\u0e01\u0e2b\u0e25\u0e07\u0e43\u0e2b\u0e25\u0e21\u0e37\u0e2d\u0e40\u0e1b\u0e25\u0e27\u0e44\u0e1f",
  "type.fire.keyword": "\u0e04\u0e27\u0e32\u0e21\u0e2b\u0e25\u0e07\u0e43\u0e2b\u0e25",
  "type.fire.element": "\u0e22\u0e34\u0e07",
  "type.fire.intro": "\u0e40\u0e1b\u0e25\u0e27\u0e44\u0e1f\u0e23\u0e34\u0e1a\u0e2b\u0e23\u0e35\u0e48\u0e43\u0e19\u0e21\u0e37\u0e2d\u0e02\u0e2d\u0e07\u0e04\u0e38\u0e13!",
  "type.fire.charm": "\u0e40\u0e21\u0e37\u0e48\u0e2d \u0e04\u0e38\u0e13 \u0e04\u0e34\u0e14 \u0e16\u0e36\u0e07 \u0e2d\u0e30\u0e44\u0e23 \u0e2a\u0e31\u0e01 \u0e2d\u0e22\u0e48\u0e32\u0e07 \u0e41\u0e25\u0e49\u0e27 \u0e04\u0e38\u0e13 \u0e01\u0e47 \u0e27\u0e34\u0e48\u0e07 \u0e44\u0e1b \u0e08\u0e19 \u0e16\u0e36\u0e07 \u0e17\u0e35\u0e48 \u0e2a\u0e38\u0e14 \u2014 \u0e44\u0e1f \u0e40\u0e1b\u0e47\u0e19 \u0e40\u0e2a\u0e19\u0e48\u0e2b\u0e4c \u0e02\u0e2d\u0e07 \u0e04\u0e38\u0e13.",
  "type.moon.name": "\u0e08\u0e34\u0e49\u0e07\u0e08\u0e2d\u0e01\u0e1d\u0e31\u0e19\u0e21\u0e37\u0e2d\u0e08\u0e31\u0e19\u0e17\u0e23\u0e4c",
  "type.moon.keyword": "\u0e08\u0e34\u0e19\u0e15\u0e19\u0e32\u0e01\u0e32\u0e23 Dreamy",
  "type.moon.element": "\u0e08\u0e31\u0e19\u0e17\u0e23\u0e4c\u0e21\u0e32\u0e42\u0e14\u0e22\u0e15\u0e25\u0e2d\u0e14",
  "type.moon.intro": "\u0e04\u0e27\u0e32\u0e21\u0e19\u0e38\u0e48\u0e21\u0e19\u0e27\u0e25 \u0e04\u0e27\u0e32\u0e21\u0e2d\u0e48\u0e2d\u0e19\u0e19\u0e38\u0e48\u0e21\u0e17\u0e35\u0e48\u0e44\u0e2b\u0e25\u0e1c\u0e48\u0e32\u0e19\u0e40\u0e2a\u0e49\u0e19\u0e02\u0e2d\u0e07\u0e04\u0e38\u0e13",
  "type.moon.charm": "\u0e08\u0e34\u0e19\u0e15\u0e19\u0e32\u0e01\u0e32\u0e23\u0e02\u0e2d\u0e07\u0e04\u0e38\u0e13\u0e0a\u0e48\u0e32\u0e07\u0e2d\u0e38\u0e14\u0e21\u0e44\u0e1b\u0e14\u0e49\u0e27\u0e22 \u0e17\u0e35\u0e48\u0e40\u0e23\u0e37\u0e48\u0e2d\u0e07\u0e23\u0e32\u0e27\u0e1a\u0e32\u0e19\u0e2a\u0e30\u0e1e\u0e23\u0e31\u0e48\u0e07 \u0e44\u0e21\u0e48\u0e27\u0e48\u0e32\u0e04\u0e38\u0e13\u0e08\u0e30\u0e44\u0e1b\u0e44\u0e2b\u0e19",
  "type.star.name": "\u0e08\u0e34\u0e49\u0e07\u0e08\u0e2d\u0e01\u0e1b\u0e23\u0e32\u0e0a\u0e0d\u0e4c\u0e21\u0e37\u0e2d\u0e14\u0e32\u0e27",
  "type.star.keyword": "\u0e1b\u0e31\u0e0d\u0e0d\u0e32 \u0e0a\u0e19",
  "type.star.element": "\u0e14\u0e32\u0e27\u0e44\u0e21\u0e48\u0e40\u0e2d\u0e32",
  "type.star.intro": "\u0e04\u0e27\u0e32\u0e21\u0e0a\u0e31\u0e14\u0e40\u0e08\u0e19 \u0e1b\u0e31\u0e0d\u0e0d\u0e32\u0e14\u0e27\u0e07\u0e14\u0e32\u0e27\u0e2d\u0e22\u0e39\u0e48\u0e43\u0e19\u0e21\u0e37\u0e2d\u0e04\u0e38\u0e13",
  "type.star.charm": "\u0e01\u0e32\u0e23 \u0e27\u0e34\u0e40\u0e04\u0e23\u0e32\u0e30\u0e2b\u0e4c \u0e2d\u0e22\u0e48\u0e32\u0e07 \u0e43\u0e08 \u0e40\u0e22\u0e47\u0e19 \u0e41\u0e25\u0e30 \u0e23\u0e2d\u0e1a\u0e04\u0e2d\u0e1a \u0e41\u0e21\u0e49 \u0e41\u0e15\u0e48 \u0e2a\u0e38\u0e19\u0e31\u0e02 \u0e08\u0e34\u0e49\u0e07\u0e08\u0e2d\u0e01 \u0e15\u0e31\u0e27 \u0e40\u0e01\u0e48\u0e32 \u0e19\u0e35\u0e49 \u0e01\u0e47 \u0e1b\u0e23\u0e30\u0e17\u0e31\u0e1a \u0e43\u0e08.",
  "type.wind.name": "\u0e08\u0e34\u0e49\u0e07\u0e08\u0e2d\u0e01\u0e2d\u0e34\u0e2a\u0e23\u0e30\u0e21\u0e37\u0e2d\u0e25\u0e21",
  "type.wind.keyword": "\u0e40\u0e2a\u0e23\u0e35\u0e20\u0e32\u0e1e",
  "type.wind.element": "\u0e25\u0e21",
  "type.wind.intro": "\u0e41\u0e1b\u0e23\u0e07\u0e01\u0e31\u0e19\u0e25\u0e21\u0e1a\u0e19\u0e1d\u0e48\u0e32\u0e21\u0e37\u0e2d",
  "type.wind.charm": "\u0e19\u0e31\u0e01\u0e1c\u0e08\u0e0d\u0e20\u0e31\u0e22\u0e1c\u0e39\u0e49\u0e01\u0e25\u0e49\u0e32\u0e2b\u0e32\u0e0d \u0e01\u0e23\u0e30\u0e42\u0e14\u0e14\u0e40\u0e02\u0e49\u0e32\u0e44\u0e1b\u0e43\u0e19\u0e17\u0e35\u0e48\u0e43\u0e2b\u0e21\u0e48\u0e46 \u0e41\u0e25\u0e30\u0e07\u0e32\u0e19\u0e43\u0e2b\u0e21\u0e48",
  "type.sun.name": "\u0e08\u0e34\u0e49\u0e07\u0e08\u0e2d\u0e01\u0e1c\u0e39\u0e49\u0e19\u0e33\u0e21\u0e37\u0e2d\u0e15\u0e30\u0e27\u0e31\u0e19",
  "type.sun.keyword": "\u0e04\u0e27\u0e32\u0e21\u0e40\u0e1b\u0e47\u0e19\u0e1c\u0e39\u0e49\u0e19\u0e4d\u0e32",
  "type.sun.element": "\u0e2d\u0e32\u0e17\u0e34\u0e15\u0e22\u0e4c",
  "type.sun.intro": "\u0e2a\u0e38\u0e23\u0e34\u0e22\u0e38\u0e1b\u0e23\u0e32\u0e04\u0e32 \u0e41\u0e1c\u0e48\u0e23\u0e31\u0e07\u0e2a\u0e35\u0e2d\u0e2d\u0e01\u0e08\u0e32\u0e01\u0e21\u0e37\u0e2d\u0e02\u0e2d\u0e07\u0e04\u0e38\u0e13",
  "type.sun.charm": "\u0e04\u0e38\u0e13 \u0e21\u0e35 \u0e04\u0e27\u0e32\u0e21 \u0e44\u0e27\u0e49 \u0e27\u0e32\u0e07\u0e43\u0e08 \u0e02\u0e2d\u0e07 \u0e1c\u0e39\u0e49 \u0e19\u0e4d\u0e32 \u2014 \u0e1c\u0e39\u0e49 \u0e04\u0e19 \u0e17\u0e4d\u0e32 \u0e15\u0e32\u0e21 \u0e18\u0e23\u0e23\u0e21\u0e0a\u0e32\u0e15\u0e34.",
  "type.cloud.name": "\u0e08\u0e34\u0e49\u0e07\u0e08\u0e2d\u0e01\u0e2a\u0e07\u0e1a\u0e21\u0e37\u0e2d\u0e40\u0e21\u0e06",
  "type.cloud.keyword": "\u0e2a\u0e31\u0e19\u0e15\u0e34\u0e20\u0e32\u0e1e",
  "type.cloud.element": "\u0e40\u0e21\u0e06",
  "type.cloud.intro": "\u0e04\u0e27\u0e32\u0e21\u0e2d\u0e48\u0e2d\u0e19\u0e42\u0e22\u0e19 \u0e04\u0e27\u0e32\u0e21\u0e2a\u0e07\u0e1a \u0e40\u0e2b\u0e21\u0e37\u0e2d\u0e19\u0e40\u0e21\u0e06\u0e25\u0e49\u0e2d\u0e21\u0e23\u0e2d\u0e1a\u0e04\u0e38\u0e13",
  "type.cloud.charm": "\u0e04\u0e27\u0e32\u0e21\u0e23\u0e2d\u0e1a\u0e04\u0e2d\u0e1a\u0e02\u0e2d\u0e07\u0e04\u0e38\u0e13 \u0e2b\u0e48\u0e2d\u0e17\u0e38\u0e01\u0e04\u0e19\u0e43\u0e19\u0e04\u0e27\u0e32\u0e21\u0e2a\u0e30\u0e14\u0e27\u0e01\u0e2a\u0e1a\u0e32\u0e22\u0e40\u0e1b\u0e47\u0e19\u0e2a\u0e21\u0e1a\u0e31\u0e15\u0e34\u0e02\u0e2d\u0e07\u0e04\u0e38\u0e13",
  "type.flower.name": "\u0e08\u0e34\u0e49\u0e07\u0e08\u0e2d\u0e01\u0e40\u0e2a\u0e19\u0e48\u0e2b\u0e4c\u0e21\u0e37\u0e2d\u0e01\u0e25\u0e35\u0e1a\u0e14\u0e2d\u0e01",
  "type.flower.keyword": "\u0e2d\u0e20\u0e34\u0e2a\u0e34\u0e17\u0e18\u0e34\u0e4c\u0e19\u0e34\u0e22\u0e21 (Charm)",
  "type.flower.element": "\u0e21\u0e38\u0e07\u0e27\u0e39",
  "type.flower.intro": "\u0e21\u0e37\u0e2d\u0e02\u0e2d\u0e07\u0e04\u0e38\u0e13\u0e01\u0e23\u0e30\u0e08\u0e32\u0e22\u0e40\u0e2a\u0e19\u0e48\u0e2b\u0e4c\u0e40\u0e2b\u0e21\u0e37\u0e2d\u0e19\u0e01\u0e25\u0e35\u0e1a\u0e14\u0e2d\u0e01",
  "type.flower.charm": "\u0e08\u0e34\u0e49\u0e07\u0e08\u0e2d\u0e01\u0e17\u0e35\u0e48\u0e44\u0e14\u0e49\u0e23\u0e31\u0e1a\u0e04\u0e27\u0e32\u0e21\u0e19\u0e34\u0e22\u0e21\u0e17\u0e35\u0e48\u0e23\u0e31\u0e01\u0e17\u0e38\u0e01\u0e17\u0e35\u0e48\u0e17\u0e35\u0e48\u0e04\u0e38\u0e13\u0e44\u0e1b \u0e2b\u0e32\u0e07 swishing \u0e21\u0e35\u0e04\u0e27\u0e32\u0e21\u0e2a\u0e38\u0e02!",
  "type.rock.name": "\u0e08\u0e34\u0e49\u0e07\u0e08\u0e2d\u0e01\u0e21\u0e38\u0e48\u0e07\u0e21\u0e31\u0e48\u0e19\u0e21\u0e37\u0e2d\u0e2b\u0e34\u0e19",
